-- Pincode -> lat/lng centroid lookup, used to notify nearby shippers,
-- transporters and brokers when a truck owner posts a new "available" truck
-- (see POST /api/truck-availability in apps/backend/src/routes/truckAvailability.js).
-- Sourced from GeoNames.org's India postal-code export (CC BY 4.0,
-- https://www.geonames.org/ — attribution required by license), averaged to
-- one centroid per 6-digit Indian pincode where the source data listed
-- multiple localities under the same code. Reference data, not user data —
-- RLS is enabled per repo convention but the read policy is open to any
-- authenticated user, and there is no insert/update/delete policy at all
-- (only ever loaded by this migration).
create table if not exists public.pincode_centroids (
  pincode text primary key,
  lat numeric(8,5) not null,
  lng numeric(8,5) not null,
  state text
);

alter table public.pincode_centroids enable row level security;

drop policy if exists "pincode_centroids_select_all" on public.pincode_centroids;
create policy "pincode_centroids_select_all" on public.pincode_centroids
  for select using (true);

