-- Haversine great-circle distance: every pincode within radius_km of
-- origin_pincode. O(n) scan over ~19k rows per call — fine for an
-- occasional write-time lookup (a new truck-availability posting), not
-- meant for a hot read path.
create or replace function public.pincodes_within_radius(origin_pincode text, radius_km numeric)
returns table(pincode text) as $$
  select p2.pincode
  from public.pincode_centroids p1
  join public.pincode_centroids p2 on true
  where p1.pincode = origin_pincode
    and 6371 * acos(least(1, greatest(-1,
          cos(radians(p1.lat)) * cos(radians(p2.lat)) * cos(radians(p2.lng) - radians(p1.lng))
          + sin(radians(p1.lat)) * sin(radians(p2.lat))
        ))) <= radius_km;
$$ language sql stable;
